<script setup>
import { computed, onMounted, reactive, watch } from 'vue'
const props=defineProps({kind:{type:String,required:true},baseUrl:{type:String,required:true},token:{type:String,required:true}})
const emit=defineEmits(['notify','changed'])
const state=reactive({loading:false,items:[],editing:null,modal:false,toolModal:false})
const skill=reactive({name:'',description:'',instructions:'',inputSchema:'{"type":"object"}',outputSchema:'{"type":"object"}',model:'main',temperature:.2,maxTokens:800})
const mcp=reactive({name:'',description:'',endpointUrl:'',authType:'NONE',secretRef:'',tools:'[]'})
const isSkill=computed(()=>props.kind==='skills')
async function request(path,options={}){const r=await fetch(`${props.baseUrl}${path}`,{method:options.method||'GET',headers:{Authorization:`Bearer ${props.token}`,...(options.body?{'Content-Type':'application/json'}:{})},body:options.body?JSON.stringify(options.body):undefined});if(!r.ok)throw new Error(r.status===409?'当前状态不允许此操作':r.status>=500?'服务暂时不可用':'请检查填写内容');return r.status===204?{}:r.json()}
async function load(){state.loading=true;try{const d=await request(isSkill.value?'/api/v1/skills':'/api/v1/mcp-connections');state.items=d.items||[]}catch(e){emit('notify',{type:'error',title:'加载失败',message:e.message})}finally{state.loading=false}}
function openCreate(){state.editing=null;if(isSkill.value)Object.assign(skill,{name:'',description:'',instructions:'',inputSchema:'{"type":"object"}',outputSchema:'{"type":"object"}',model:'main',temperature:.2,maxTokens:800});else Object.assign(mcp,{name:'',description:'',endpointUrl:'',authType:'NONE',secretRef:'',tools:'[]'});state.modal=true}
function openEdit(item){state.editing=item;if(isSkill.value){const d=item.draft_definition||{};Object.assign(skill,{name:item.name,description:item.description,instructions:d.instructions||'',inputSchema:JSON.stringify(d.input_schema||{type:'object'},null,2),outputSchema:JSON.stringify(d.output_schema||{type:'object'},null,2),model:d.model||'main',temperature:d.temperature??.2,maxTokens:d.max_tokens||800})}else Object.assign(mcp,{name:item.name,description:item.description,endpointUrl:item.endpoint_url,authType:item.auth_type,secretRef:item.secret_ref||'',tools:JSON.stringify(item.tools||[],null,2)});state.modal=true}
function jsonValue(value,label){try{return JSON.parse(value)}catch{throw new Error(`${label} 不是有效 JSON`)}}
async function save(){try{let body,path;if(isSkill.value){body={name:skill.name,description:skill.description,instructions:skill.instructions,input_schema:jsonValue(skill.inputSchema,'输入结构'),output_schema:jsonValue(skill.outputSchema,'输出结构'),model:skill.model,temperature:Number(skill.temperature),max_tokens:Number(skill.maxTokens)};path=state.editing?`/api/v1/skills/${state.editing.skill_id}`:'/api/v1/skills'}else{body={name:mcp.name,description:mcp.description,endpoint_url:mcp.endpointUrl,auth_type:mcp.authType,secret_ref:mcp.secretRef};path=state.editing?`/api/v1/mcp-connections/${state.editing.connection_id}`:'/api/v1/mcp-connections'}await request(path,{method:state.editing?'PUT':'POST',body});state.modal=false;await load();emit('changed');emit('notify',{type:'success',title:'已保存',message:''})}catch(e){emit('notify',{type:'error',title:'保存失败',message:e.message})}}
async function publish(item){try{await request(`/api/v1/skills/${item.skill_id}/publish`,{method:'POST'});await load();emit('changed');emit('notify',{type:'success',title:'Skill 已发布',message:'画布现在可以固定使用该版本'})}catch(e){emit('notify',{type:'error',title:'发布失败',message:e.message})}}
async function saveTools(item){try{await request(`/api/v1/mcp-connections/${item.connection_id}/tools`,{method:'PUT',body:{tools:jsonValue(mcp.tools,'工具目录')}});state.toolModal=false;await load();emit('changed');emit('notify',{type:'success',title:'工具目录已更新',message:''})}catch(e){emit('notify',{type:'error',title:'更新失败',message:e.message})}}
async function discover(item){try{await request(`/api/v1/mcp-connections/${item.connection_id}/discover`,{method:'POST'});await load();emit('changed');emit('notify',{type:'success',title:'连接成功',message:'已同步远端工具目录'})}catch(e){emit('notify',{type:'error',title:'连接失败',message:e.message})}}
function openTools(item){state.editing=item;mcp.tools=JSON.stringify(item.tools||[],null,2);state.toolModal=true}
async function remove(item){if(!confirm(`确定删除“${item.name}”吗？已发布工作流中的快照不会改变。`))return;try{await request(isSkill.value?`/api/v1/skills/${item.skill_id}`:`/api/v1/mcp-connections/${item.connection_id}`,{method:'DELETE'});await load();emit('changed')}catch(e){emit('notify',{type:'error',title:'删除失败',message:e.message})}}
onMounted(load)
watch(()=>props.kind,()=>{state.items=[];state.modal=false;state.toolModal=false;load()})
</script>
<template><section class="integration-page"><div class="integration-toolbar"><div><strong>{{ isSkill?'可复用 Skill':'MCP 连接' }}</strong><span>{{ isSkill?'将稳定指令、输入输出契约发布为版本，在智能体与 Workflow 中复用。':'集中管理远程 MCP Server、鉴权引用和可调用工具目录。' }}</span></div><button class="primary" @click="openCreate">＋ {{ isSkill?'新建 Skill':'接入 MCP' }}</button></div>
<div class="integration-grid"><article v-for="item in state.items" :key="item.skill_id||item.connection_id" class="integration-card"><header><span class="mark">{{ isSkill?'S':'M' }}</span><span class="status" :class="item.status.toLowerCase()">{{ item.status==='PUBLISHED'?'已发布':item.status==='READY'?'已就绪':'草稿' }}</span></header><h3>{{ item.name }}</h3><p>{{ item.description||'暂无描述' }}</p><div class="meta" v-if="isSkill">最新版本 v{{ item.latest_version_no||0 }} · {{ item.draft_definition?.model||'main' }}</div><div class="meta" v-else>{{ item.transport }} · {{ (item.tools||[]).length }} 个工具<br><code>{{ item.endpoint_url }}</code></div><footer><button @click="openEdit(item)">编辑</button><button v-if="isSkill" :disabled="!item.name" @click="publish(item)">发布版本</button><template v-else><button :disabled="item.auth_type!=='NONE'" @click="discover(item)">连接并发现</button><button @click="openTools(item)">工具目录</button></template><button class="danger" @click="remove(item)">删除</button></footer></article><button class="create-card" @click="openCreate"><b>＋</b><strong>{{ isSkill?'创建新 Skill':'连接 MCP Server' }}</strong><small>{{ isSkill?'定义指令、契约和模型参数':'Streamable HTTP · 密钥引用' }}</small></button></div>
<div v-if="state.modal" class="modal" @pointerdown.self="state.modal=false"><form class="modal-card" @submit.prevent="save"><header><div><small>Powflow Integration</small><h2>{{ state.editing?'编辑':'新建' }}{{ isSkill?' Skill':' MCP 连接' }}</h2></div><button type="button" @click="state.modal=false">×</button></header><template v-if="isSkill"><label>名称<input v-model="skill.name" required maxlength="128"></label><label>描述<textarea v-model="skill.description" rows="2"></textarea></label><label>Skill 指令<textarea v-model="skill.instructions" required rows="7" placeholder="描述角色、边界、处理步骤和输出要求"></textarea></label><div class="two"><label>模型池<input v-model="skill.model"></label><label>最大 Token<input v-model.number="skill.maxTokens" type="number" min="1" max="32768"></label></div><div class="two"><label>输入 JSON Schema<textarea v-model="skill.inputSchema" rows="5"></textarea></label><label>输出 JSON Schema<textarea v-model="skill.outputSchema" rows="5"></textarea></label></div></template><template v-else><label>名称<input v-model="mcp.name" required maxlength="128"></label><label>描述<textarea v-model="mcp.description" rows="2"></textarea></label><label>Streamable HTTP 端点<input v-model="mcp.endpointUrl" required placeholder="https://example.com/mcp"></label><div class="two"><label>鉴权方式<select v-model="mcp.authType"><option value="NONE">无鉴权</option><option value="BEARER">Bearer</option><option value="API_KEY">API Key</option></select></label><label>密钥引用<input v-model="mcp.secretRef" :required="mcp.authType!=='NONE'" placeholder="workflow secret ref"></label></div><p class="privacy">只保存密钥引用，密钥明文不会进入连接记录、工作流或运行日志。</p></template><footer><button type="button" @click="state.modal=false">取消</button><button class="primary" type="submit">保存</button></footer></form></div>
<div v-if="state.toolModal" class="modal" @pointerdown.self="state.toolModal=false"><form class="modal-card" @submit.prevent="saveTools(state.editing)"><header><div><small>MCP Tool Catalog</small><h2>工具目录</h2></div><button type="button" @click="state.toolModal=false">×</button></header><p class="privacy">粘贴 tools/list 返回的 tools 数组。工具注解来自远端服务，发布前仍需人工核对风险。</p><label>工具 JSON<textarea v-model="mcp.tools" rows="16"></textarea></label><footer><button type="button" @click="state.toolModal=false">取消</button><button class="primary">保存目录</button></footer></form></div></section></template>
<style scoped>.integration-page{max-width:1240px;margin:0 auto}.integration-toolbar{display:flex;justify-content:space-between;gap:24px;align-items:center;margin-bottom:18px}.integration-toolbar>div{display:grid;gap:6px}.integration-toolbar span,.meta,.privacy{color:var(--workspace-muted);font-size:12px;line-height:1.6}.integration-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.integration-card,.create-card{min-height:242px;padding:22px;border:1px solid rgba(127,127,127,.16);border-radius:22px;color:inherit;background:rgba(255,255,255,.78);box-shadow:0 14px 38px rgba(0,0,0,.07);text-align:left}.integration-card header,.integration-card footer,.modal-card header,.modal-card footer{display:flex;align-items:center;justify-content:space-between;gap:10px}.mark{display:grid;place-items:center;width:44px;height:44px;border-radius:14px;color:#fff;background:linear-gradient(145deg,#168bff,#675df6);font-weight:800}.status{padding:5px 9px;border-radius:999px;background:rgba(127,127,127,.1);font-size:10px}.status.published,.status.ready{color:#1f9d5a;background:rgba(31,157,90,.12)}h3{margin:20px 0 8px;font-size:20px}p{min-height:42px;margin:0 0 14px;color:var(--workspace-muted);line-height:1.55}.meta{min-height:42px}.meta code{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.integration-card footer{justify-content:flex-start;margin-top:18px}.integration-card button,.modal-card button,.integration-toolbar button{min-height:36px;padding:0 12px;border:1px solid rgba(127,127,127,.2);border-radius:11px;color:inherit;background:rgba(127,127,127,.08)}button.primary{border:0;color:white;background:#0071e3}.danger{color:#ff453a!important}.create-card{display:grid;place-items:center;align-content:center;gap:8px;border-style:dashed;background:rgba(0,113,227,.04)}.create-card b{font-size:28px}.create-card small{color:var(--workspace-muted)}.modal{position:fixed;z-index:100;inset:0;display:grid;place-items:center;padding:20px;background:rgba(4,8,16,.56);backdrop-filter:blur(12px)}.modal-card{display:grid;gap:15px;width:min(680px,100%);max-height:calc(100dvh - 40px);overflow:auto;padding:25px;border:1px solid rgba(127,127,127,.24);border-radius:26px;color:var(--workspace-text);background:rgba(28,28,31,.96);box-shadow:0 32px 90px rgba(0,0,0,.4)}.modal-card h2{margin:4px 0}.modal-card header>button{width:34px;padding:0;border-radius:50%}.modal-card label{display:grid;gap:7px;color:var(--workspace-muted);font-size:11px}.modal-card input,.modal-card textarea,.modal-card select{width:100%;padding:11px 13px;border:1px solid rgba(127,127,127,.22);border-radius:12px;color:var(--workspace-text);background:rgba(127,127,127,.09)}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.modal-card footer{justify-content:flex-end}:global(html[data-theme="dark"]) .integration-card,:global(html[data-theme="dark"]) .create-card{background:rgba(28,28,30,.78)}:global(html[data-theme="light"]) .modal-card{background:rgba(255,255,255,.97)}@media(max-width:900px){.integration-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:620px){.integration-toolbar{align-items:flex-start;flex-direction:column}.integration-grid{grid-template-columns:1fr}.two{grid-template-columns:1fr}.modal-card{padding:19px;border-radius:22px}}</style>
